WITH ranked AS (SELECT * FROM sessions QUALIFY ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at NULLS FIRST, id) = 1) SELECT browser, COUNT(CASE WHEN device = 'desktop' THEN 1 END) AS desktop_count, SIZE(COLLECT_SET(device)) AS num_devices, SORT_ARRAY(COLLECT_SET(country)) AS country_list, COUNT(*) FILTER (WHERE device = 'desktop') AS desktop_rows, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, MAX(started_at) AS last_seen FROM ranked GROUP BY browser
